import{_ as t,o as a,c as s,ae as i}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"Active Context Store and Tab Surface Framework","description":"","frontmatter":{"work_package_id":"WP01","title":"Active Context Store and Tab Surface Framework","lane":"done","dependencies":[],"base_branch":"main","base_commit":"d96fb53a83841cde41a446e6c69ba26e888cd207","created_at":"2026-03-01T13:29:17.148173+00:00","subtasks":["T001","T002","T003","T004","T005"],"phase":"Phase 1 - Foundation","assignee":"","agent":"claude-haiku","shell_pid":"53948","review_status":"approved","reviewed_by":"Koosha Paridehpour","history":[{"timestamp":"2026-02-27T00:00:00Z","lane":"planned","agent":"system","shell_pid":"","action":"Prompt generated via /spec-kitty.tasks"}]},"headers":[],"relativePath":"specs/016-workspace-lane-session-ui-tabs/tasks/WP01-active-context-store-and-tab-framework.md","filePath":"specs/016-workspace-lane-session-ui-tabs/tasks/WP01-active-context-store-and-tab-framework.md"}'),o={name:"specs/016-workspace-lane-session-ui-tabs/tasks/WP01-active-context-store-and-tab-framework.md"};function n(r,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="work-package-prompt-wp01-active-context-store-and-tab-surface-framework" tabindex="-1">Work Package Prompt: WP01 - Active Context Store and Tab Surface Framework <a class="header-anchor" href="#work-package-prompt-wp01-active-context-store-and-tab-surface-framework" aria-label="Permalink to &quot;Work Package Prompt: WP01 - Active Context Store and Tab Surface Framework&quot;">​</a></h1><h2 id="objectives-success-criteria" tabindex="-1">Objectives &amp; Success Criteria <a class="header-anchor" href="#objectives-success-criteria" aria-label="Permalink to &quot;Objectives &amp; Success Criteria&quot;">​</a></h2><ul><li>Implement the shared active context store as the single source of truth for the current workspace/lane/session triple.</li><li>Implement the base tab surface component that binds to the active context.</li><li>Implement the tab bar with selection, ordering, reordering, and pinning.</li><li>Implement tab state persistence across runtime restarts.</li></ul><p>Success criteria:</p><ul><li>Context store emits change events when the active triple changes.</li><li>Tab bar renders all five tab types with correct selection highlighting.</li><li>Tab selection and ordering persist across restarts and load within 100ms.</li><li>Tab surfaces bind to the active context and react to changes.</li></ul><h2 id="context-constraints" tabindex="-1">Context &amp; Constraints <a class="header-anchor" href="#context-constraints" aria-label="Permalink to &quot;Context &amp; Constraints&quot;">​</a></h2><ul><li>Constitution: <code>docs/reference/constitution.md</code></li><li>Plan: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/016-workspace-lane-session-ui-tabs/plan.md</code></li><li>Spec: <code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/kitty-specs/016-workspace-lane-session-ui-tabs/spec.md</code></li><li>Internal event bus: <code>apps/runtime/src/protocol/bus.ts</code> (spec 001)</li><li>Terminal registry: spec 014</li><li>Lane/session lifecycle: specs 008, 009</li></ul><p>Constraints:</p><ul><li>Tab UI must not block the main thread.</li><li>All actions must be keyboard-accessible.</li><li>Keep files under 500 lines.</li><li>TypeScript + Bun + ElectroBun.</li></ul><p>Implementation command:</p><ul><li><code>spec-kitty implement WP01</code></li></ul><h2 id="subtasks-detailed-guidance" tabindex="-1">Subtasks &amp; Detailed Guidance <a class="header-anchor" href="#subtasks-detailed-guidance" aria-label="Permalink to &quot;Subtasks &amp; Detailed Guidance&quot;">​</a></h2><h3 id="subtask-t001-implement-shared-active-context-store" tabindex="-1">Subtask T001 - Implement shared active context store <a class="header-anchor" href="#subtask-t001-implement-shared-active-context-store" aria-label="Permalink to &quot;Subtask T001 - Implement shared active context store&quot;">​</a></h3><ul><li>Purpose: provide a single source of truth for the current workspace/lane/session driving all tab content.</li><li>Steps: <ol><li>Implement <code>ActiveContextStore</code> in <code>apps/desktop/src/tabs/context_switch.ts</code>: a. Hold current context: <code>{ workspaceId: string, laneId: string, sessionId: string } | null</code>. b. Expose <code>setContext(context)</code>: update the active context and emit a change event. c. Expose <code>getContext()</code>: return the current context. d. Expose <code>onContextChange(callback)</code>: register a listener for context changes. e. Expose <code>clearContext()</code>: set context to null (no active context).</li><li>Implement change event: a. Emit event with both previous and new context for comparison. b. Publish on the internal bus as <code>context.active.changed</code>.</li><li>Implement debouncing for rapid changes: a. If multiple <code>setContext</code> calls arrive within 50ms, only emit the final one. b. This prevents intermediate render flicker during rapid lane switches.</li><li>Implement context validation: a. Before accepting a new context, validate that the workspace, lane, and session exist. b. If validation fails, reject the change and emit a <code>context.validation.failed</code> event.</li><li>Export the store as a singleton for app-wide use.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/context_switch.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: set context, assert change event emitted with correct previous/new values.</li><li>Unit test: rapid context changes, assert only final context is emitted.</li><li>Unit test: invalid context, assert rejection with validation error.</li><li>Unit test: clear context, assert null context and change event.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t002-implement-base-tab-surface-component" tabindex="-1">Subtask T002 - Implement base tab surface component <a class="header-anchor" href="#subtask-t002-implement-base-tab-surface-component" aria-label="Permalink to &quot;Subtask T002 - Implement base tab surface component&quot;">​</a></h3><ul><li>Purpose: define the abstract base for all tab surfaces with context binding and lifecycle management.</li><li>Steps: <ol><li>Implement <code>TabSurface</code> base class/interface in <code>apps/desktop/src/tabs/tab_surface.ts</code>: a. Properties: <code>tabId</code>, <code>tabType</code> (terminal|agent|session|chat|project), <code>label</code>, <code>isActive</code>. b. <code>onContextChange(context)</code>: called when the active context changes; subclasses implement to update content. c. <code>onActivate()</code>: called when this tab becomes the selected tab. d. <code>onDeactivate()</code>: called when another tab becomes selected. e. <code>render()</code>: render the tab content (subclass responsibility). f. <code>getState()</code>: return serializable tab state for persistence. g. <code>restoreState(state)</code>: restore from persisted state.</li><li>Implement context binding: a. On construction, subscribe to the active context store&#39;s change events. b. Call <code>onContextChange</code> with the new context. c. If context change fails for this tab, set a <code>staleContext</code> flag.</li><li>Implement error boundary: a. If <code>render()</code> throws, display an error state within the tab rather than crashing. b. Log the error and emit a tab error event.</li><li>Export the base class for tab implementations (WP02).</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/tab_surface.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: create mock tab surface, change context, assert <code>onContextChange</code> called.</li><li>Unit test: simulate render error, assert error state displayed.</li><li>Unit test: activate/deactivate lifecycle calls.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t003-implement-tab-bar-component" tabindex="-1">Subtask T003 - Implement tab bar component <a class="header-anchor" href="#subtask-t003-implement-tab-bar-component" aria-label="Permalink to &quot;Subtask T003 - Implement tab bar component&quot;">​</a></h3><ul><li>Purpose: render the tab bar with selection, ordering, reordering, and pinning controls.</li><li>Steps: <ol><li>Implement <code>TabBar</code> in <code>apps/desktop/src/tabs/tab_bar.ts</code>: a. Accept a list of <code>TabSurface</code> instances. b. Render tab headers with labels and active/inactive styling. c. Handle tab selection: click or keyboard shortcut activates a tab. d. Handle tab reordering: drag-and-drop (mouse) and keyboard-based reorder. e. Handle tab pinning: pinned tabs appear first and cannot be reordered past other pinned tabs.</li><li>Implement selection management: a. Track the currently selected tab. b. On selection change, call <code>onDeactivate</code> on previous and <code>onActivate</code> on new tab. c. Emit <code>tab.selected</code> event on the bus.</li><li>Implement visual indicators: a. Active tab gets distinct styling. b. Stale-context tab gets a warning indicator (yellow dot or similar).</li><li>Implement keyboard accessibility: a. Tab/Shift-Tab moves focus between tab headers. b. Enter/Space activates the focused tab. c. Arrow keys move between adjacent tabs.</li><li>FR-016-007: support tab reordering and pinning as user preferences.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/tab_bar.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: render tab bar with 5 tabs, select each, verify selection state.</li><li>Unit test: reorder tabs, verify new order.</li><li>Unit test: pin tab, verify it appears first.</li><li>Unit test: keyboard navigation cycles through tabs.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t004-implement-tab-state-persistence" tabindex="-1">Subtask T004 - Implement tab state persistence <a class="header-anchor" href="#subtask-t004-implement-tab-state-persistence" aria-label="Permalink to &quot;Subtask T004 - Implement tab state persistence&quot;">​</a></h3><ul><li>Purpose: persist tab selection, order, and per-tab state across runtime restarts.</li><li>Steps: <ol><li>Implement <code>TabPersistence</code> in <code>apps/desktop/src/tabs/tab_persistence.ts</code>: a. Serialize: current selected tab, tab order, per-tab state (from <code>getState()</code>). b. Storage: file-backed JSON at <code>~/.helios/data/tab_state.json</code>. c. <code>save()</code>: write current state to disk; debounce at 500ms to avoid write storms. d. <code>load(): TabPersistedState | null</code>: read from disk on startup. e. <code>restore(tabs: TabSurface[])</code>: apply persisted state to tab instances.</li><li>Implement load timing: a. Load must complete within 100ms of startup (NFR-016-003 related). b. If load fails or file is corrupt, use defaults (terminal tab selected, default order).</li><li>Wire persistence into tab bar: a. On tab selection change -&gt; schedule save. b. On tab reorder -&gt; schedule save. c. On graceful shutdown -&gt; immediate flush.</li><li>FR-016-006: tab selection state persists across runtime restarts.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/src/tabs/tab_persistence.ts</code></li></ul></li><li>Validation: <ul><li>Unit test: save tab state, reload, verify selection and order match.</li><li>Unit test: corrupt file, verify defaults loaded.</li><li>Benchmark: verify load completes in &lt;100ms.</li></ul></li><li>Parallel: No.</li></ul><h3 id="subtask-t005-add-unit-tests-for-context-store-tab-bar-and-persistence" tabindex="-1">Subtask T005 - Add unit tests for context store, tab bar, and persistence <a class="header-anchor" href="#subtask-t005-add-unit-tests-for-context-store-tab-bar-and-persistence" aria-label="Permalink to &quot;Subtask T005 - Add unit tests for context store, tab bar, and persistence&quot;">​</a></h3><ul><li>Purpose: lock behavior before tab surface implementations.</li><li>Steps: <ol><li>Create <code>apps/desktop/tests/unit/tabs/context_switch.test.ts</code>: a. Test context set/get/clear lifecycle. b. Test change event emission with previous/new values. c. Test debouncing of rapid changes. d. Test validation rejection for invalid contexts.</li><li>Create <code>apps/desktop/tests/unit/tabs/tab_bar.test.ts</code>: a. Test tab selection management. b. Test reordering and pinning. c. Test keyboard navigation. d. Test stale-context indicator display.</li><li>Create <code>apps/desktop/tests/unit/tabs/tab_persistence.test.ts</code>: a. Test save/load cycle. b. Test corrupt file recovery. c. Test debounced saves.</li><li>Aim for &gt;=85% line coverage.</li></ol></li><li>Files: <ul><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/context_switch.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/tab_bar.test.ts</code></li><li><code>/Users/kooshapari/CodeProjects/Phenotype/repos/heliosApp/apps/desktop/tests/unit/tabs/tab_persistence.test.ts</code></li></ul></li><li>Parallel: Yes (after T001-T004 interfaces are stable).</li></ul><h2 id="test-strategy" tabindex="-1">Test Strategy <a class="header-anchor" href="#test-strategy" aria-label="Permalink to &quot;Test Strategy&quot;">​</a></h2><ul><li>Unit tests with Vitest for store, bar, and persistence logic.</li><li>Mock context changes to verify event propagation.</li><li>Benchmark persistence load timing.</li><li>Aim for &gt;=85% line coverage.</li></ul><h2 id="risks-mitigations" tabindex="-1">Risks &amp; Mitigations <a class="header-anchor" href="#risks-mitigations" aria-label="Permalink to &quot;Risks &amp; Mitigations&quot;">​</a></h2><ul><li>Risk: context store race conditions during rapid switches.</li><li>Mitigation: debouncing with latest-wins semantics.</li><li>Risk: persistence file corruption.</li><li>Mitigation: graceful fallback to defaults with warning.</li></ul><h2 id="review-guidance" tabindex="-1">Review Guidance <a class="header-anchor" href="#review-guidance" aria-label="Permalink to &quot;Review Guidance&quot;">​</a></h2><ul><li>Confirm context store is a true singleton with no alternative state sources.</li><li>Confirm debouncing prevents intermediate renders.</li><li>Confirm tab bar keyboard accessibility covers all required patterns.</li><li>Confirm persistence load timing meets 100ms target.</li></ul><h2 id="activity-log" tabindex="-1">Activity Log <a class="header-anchor" href="#activity-log" aria-label="Permalink to &quot;Activity Log&quot;">​</a></h2><ul><li>2026-02-27T00:00:00Z -- system -- lane=planned -- Prompt created.</li><li>2026-03-01T13:29:17Z – claude-haiku – shell_pid=53948 – lane=doing – Assigned agent via workflow command</li><li>2026-03-01T13:32:31Z – claude-haiku – shell_pid=53948 – lane=done – Implemented WP01</li></ul>',30)])])}const h=t(o,[["render",n]]);export{u as __pageData,h as default};
